static List<String> order(Map<String,Long> c){
    List<String> es=new ArrayList<>(c.keySet());
    Collections.sort(es);
    if(c.containsKey("C")){
        es.remove("C");
        es.remove("H");
        if(c.containsKey("H"))es.add(0,"H");
        es.add(0,"C");
    }
    return es;
