    for(String e:order(c)){
        s.append(e);
        if(c.get(e)!=1)s.append(c.get(e));
    }
    if(q!=0){
        s.append('^');
        if(Math.abs(q)!=1)s.append(Math.abs(q));
        s.append(q>0?'+':'-');
    }
    return s.toString();
